[4002] = {id=4002,chinese=[[<img src="ui_icon_gzsm_8q_8qgz.png" width="125" height="47">
胜利：
不犯规的情况下，先打进所有目标球后，再将黑8打进即为获胜/n
失败：
1、还未将所有目标球打进之前，提前打进黑8
2、在击打最后一颗球时，白球与黑8同时进袋
3、在同一局比赛中，连续犯规达到3次直接判负/n
全色球：
<img src="ui_icon_gzsm_8q_qsq.png" width="613" height="60">/n
花色球：
<img src="ui_icon_gzsm_8q_hsq.png" width="613" height="60">/n
<img src="ui_icon_gzsm_8q_wjxx.png" width="613" height="102">/n
如何确定目标球：
未确定目标球时，通过击入全色球或花色球确定目标球/n
目标球信息：
球桌上剩余的目标球数量/n
回合倒计时：
倒计时结束前必须要出杆，否则被视为犯规/n
开球打进黑8：
若开球打进黑8，将黑8取出放在离置球点最近的位置上，继续击球]],chinese_gs="",},
[4003] = {id=4003,chinese="斯诺克",chinese_gs="",},
[4004] = {id=4004,chinese=[[<img src="ui_icon_gzsm_snk_gzsm.png" width="191" height="47">
胜利：
所有球全部入袋后,分数高的一方获胜/n
目标球分值：
<img src="ui_icon_gzsm_snk_mbqfz.png" width="613" height="94">/n
击球说明：
1.红球有多颗（6、10、15），其他颜色彩球各1颗，红球、彩球交替击打
2.当球桌上有红球剩余时，交替击打红球和彩球，红球进袋不再摆回台面，彩球进袋后放回置球点
3.当球桌上没有红球时，按彩球分值从小到大，依次击打，此时彩球进袋不再取出/n
犯规说明：
1.空杆，白球未碰到任何球，罚4~7分
2.白球入袋，对方获得手中球，罚4~7分
3.连续击打红球，罚7分
4.未先击打目标球，罚4~7分
5.非目标球入袋，罚4~7分/n
超分/被超分：
当领先/落后的分值高于桌面上最大分值时，即为超分/ 被超分/n
让杆说明：
1.当给对方做成斯诺克时，对方解球失败，可以选择让杆， 回到解球前的状态并继续解球
2.每次斯诺克最多让杆3次，超分后也不可以继续让杆]],chinese_gs="",},
[4005] = {id=4005,chinese="欢乐血流",chinese_gs="",},
[4006] = {id=4006,chinese=[[<img src="ui_icon_gzsm_hldrxl_wfsm.png" width="125" height="47">
1.3人成局，按顺序轮流击球，各自为战
2.桌面上所有数字球都是目标球
3.每场比赛的球库中有若干球，每打进一颗球，将从球库中取出一颗球放到桌面上
4.每次击球后，根据击球结果向其他两家结算一次
5.所有球都被打进后，对局结束 /n
<img src="ui_icon_gzsm_hldrxl_gzsm.png" width="125" height="47">
金币 = 底分 * 击球得分 * 撞击倍数 * 牌型倍数 * 基础倍数
1.击球得分 = 球号 * 洞口倍数
2.牌型倍数 = 牌型组合倍数 * 牌型组合的数字和（例如：牌型333的倍数 = 炸弹25倍 * （3+3+3））
3.初始基础倍数为1，每打出一个牌型，会根据牌型的类型增加
4.扣分规则：白球进袋，击球得分为-5，超时不击球，击球得分为-1000
5.撞击不同数量的数字圈可获得不同的撞击倍数。（撞击1~7个分别为1倍、1倍、1倍、1.1倍、1.1倍、1.1倍、1.2倍）/n
<img src="ui_icon_gzsm_hldrxl_pxgz.png" width="125" height="47">
<img src="ui_icon_gzsm_hldrxl_pxgzt.png" width="613" height="106">/n
<img src="ui_icon_gzsm_hldrxl_fksk.png" width="125" height="47">
1.一人破产或球库中的球全部取出后进入疯狂时刻
2.进入疯狂时刻后，洞口数字x2，封顶倍率x2]],chinese_gs="",},
