[6000112] = {id=6000112,chinese="在对局中点击分析按钮使用，可用于局面优劣分析；也可用于结算时复盘分析；如对局中已使用分析卡，则复盘分析时无需使用即可复盘。",chinese_gs="",},
[6000122] = {id=6000122,chinese="在对局中点击悔棋按钮使用，对方同意后可进行1次悔棋；残局中无需对方同意，可立即悔棋。",chinese_gs="",},
[6000132] = {id=6000132,chinese="在对局中点击漏招按钮使用，可获得漏吃、漏杀、被吃反悔等特权，每次使用后可获得3次提示。",chinese_gs="",},
[6000142] = {id=6000142,chinese="在对局中点击支招按钮使用，可获得2次最优解支招；如残局中使用无法最优解，会自动重置局面进行支招。",chinese_gs="",},
[6000152] = {id=6000152,chinese="在揭棋对局中点击透视按钮使用，可看到一颗己方被吃的暗子；",chinese_gs="",},
[6000162] = {id=6000162,chinese="在揭棋对局中点击找车按钮使用，可获得3个棋子提示，其中1个棋子必定为车。",chinese_gs="",},
[6000172] = {id=6000172,chinese="在对局中点击提和按钮使用，对方同意后该局为和棋。",chinese_gs="",},
[6000182] = {id=6000182,chinese="在部分对局中点击加时按钮使用，可为自己增加当前回合走棋时间10秒和己方局时10秒。",chinese_gs="",},
