[10118100] = {id=10118100,chinese="行棋术语",chinese_gs="",},
[10100101] = {id=10100101,chinese="象棋有两个阵营，<font color=#f80421>红色棋子</font>一方为<font color=#f80421>红色阵营</font>，游戏中称为<font color=#048404>先手方</font>",chinese_gs="",},
[10100102] = {id=10100102,chinese="<font color=#000000>黑色棋子</font>一方为<font color=#f80421>黑方阵营</font>，游戏中称为<font color=#048404>后手方</font>",chinese_gs="",},
[10100103] = {id=10100103,chinese="棋盘中间的<font color=#048404>楚河汉界</font>，一般被称呼<font color=#048404>河界</font>",chinese_gs="",},
[10100104] = {id=10100104,chinese="<font color=#f80421>帅</font>/<font color=#000000>将</font>、<font color=#f80421>仕</font>/<font color=#000000>士</font>所在的<font color=#048404>米字方格</font>，一般被称呼<font color=#048404>九宫</font>，代表九个线条交叉点。",chinese_gs="",},
[10100105] = {id=10100105,chinese="下方为己方，标注<font color=#048404>一至九</font>，上方棋盘为敌方，标注<font color=#048404>9至1</font>，这些数字称为<font color=#048404>位标</font>",chinese_gs="",},
[10101101] = {id=10101101,chinese="棋盘中第五条竖线称为<font color=#048404>中线</font>",chinese_gs="",},
[10101102] = {id=10101102,chinese="棋盘中第四和第六条竖线，称为<font color=#048404>肋道</font>",chinese_gs="",},
[10101103] = {id=10101103,chinese="棋盘中第一和第九条竖线，称为<font color=#048404>边线</font>",chinese_gs="",},
[1101104] = {id=1101104,chinese="中线",chinese_gs="",},
[1101105] = {id=1101105,chinese="肋道",chinese_gs="",},
[1101106] = {id=1101106,chinese="边线",chinese_gs="",},
[10102101] = {id=10102101,chinese="以棋手为准，双方由下至上第一条横线称为<font color=#048404>底线</font>",chinese_gs="",},
[10102102] = {id=10102102,chinese="以棋手为准，双方由下至上第二条横线称为<font color=#048404>底二线</font>",chinese_gs="",},
[10102103] = {id=10102103,chinese="以棋手为准，双方由下至上第三条横线称为<font color=#048404>宫顶线</font>",chinese_gs="",},
[10102104] = {id=10102104,chinese="以棋手为准，双方由下至上第四条横线称为<font color=#048404>兵行线/卒林线</font>，这是兵和卒的初始位置",chinese_gs="",},
[10102105] = {id=10102105,chinese="河界两边的线称为<font color=#048404>河界线</font>，这是兵和卒的初始位置",chinese_gs="",},
[1102106] = {id=1102106,chinese="底线",chinese_gs="",},
[1102107] = {id=1102107,chinese="底二线",chinese_gs="",},
[1102108] = {id=1102108,chinese="宫顶线",chinese_gs="",},
[1102109] = {id=1102109,chinese="兵行线",chinese_gs="",},
[1102110] = {id=1102110,chinese="河界线",chinese_gs="",},
[1102111] = {id=1102111,chinese="卒林线",chinese_gs="",},
[10110101] = {id=10110101,chinese="<font color=#f80421>帅</font>/<font color=#000000>将</font>只能在<font color=#048404>九宫格</font>内移动，不能走出<font color=#048404>九宫格</font>",chinese_gs="",},
[10110102] = {id=10110102,chinese="<font color=#f80421>帅</font>/<font color=#000000>将</font>沿九宫格<font color=#048404>横线和竖线</font>移动，且每次只能移动<font color=#048404>一格</font>，这里的标记点就是可移动到的位置点",chinese_gs="",},
[10110103] = {id=10110103,chinese="例如：手指的红方<font color=#f80421>帅</font>所在位置，根据规则只可向<font color=#048404>上、左、右</font>移动一格",chinese_gs="",},
[10110104] = {id=10110104,chinese="而手指的黑方<font color=#000000>将</font>所在位置，则可向<font color=#048404>上、下、左、右</font>移动一格",chinese_gs="",},
[10110105] = {id=10110105,chinese="注意！对局时<font color=#f80421>帅</font>/<font color=#000000>将</font>中间无棋子时，不可在同一竖线上，所以，这个<font color=#f80421>帅</font>此时只能向<font color=#048404>下、右</font>移动一格",chinese_gs="",},
[10110201] = {id=10110201,chinese="<font color=#f80421>帅</font>/<font color=#000000>将</font>的走棋和吃棋方式相同，即沿<font color=#048404>九宫的横线和竖线移动一格</font>吃子",chinese_gs="",},
[10110202] = {id=10110202,chinese="这里的星星，就是当前<font color=#f80421>帅</font>/<font color=#000000>将</font>可以<font color=#048404>吃棋</font>的位置",chinese_gs="",},
[10110203] = {id=10110203,chinese="我们再来看这几个星星，由于<font color=#f80421>帅</font>不能斜线移动，所以<font color=#f80421>帅</font>是<font color=#048404不可以吃掉></font>这颗星星的",chinese_gs="",},
[10110204] = {id=10110204,chinese="由于<font color=#f80421>帅</font>不能走出九宫格，所以<font color=#f80421>帅</font>也是<font color=#048404>不可以吃掉</font>这颗星星的",chinese_gs="",},
[10110205] = {id=10110205,chinese="这颗星星的虽然在九宫格，但是<font color=#f80421>帅</font>每次只能移动一格，所以<font color=#f80421>帅</font>也是<font color=#048404>不可以在下一步</font>吃掉这颗星星的",chinese_gs="",},
[10110206] = {id=10110206,chinese="只有这颗星星，在<font color=#f80421>帅</font>旁边横线一格距离，所以<font color=#f80421>帅</font>可以移动过去<font color=#048404>吃掉</font>这颗星星",chinese_gs="",},
[10110207] = {id=10110207,chinese="接下来，就让我们去习题实操练习下怎么走<font color=#f80421>帅</font>和吃棋吧！",chinese_gs="",},
[10110301] = {id=10110301,chinese="点击<font color=#f80421>帅</font>即可选中他，然后再点击<font color=#048404>星星</font>，即可移动到星星位置。试试吧，把<font color=#f80421>帅</font>移动到<font color=#048404>星星</font>位置！",chinese_gs="",},
[10110302] = {id=10110302,chinese="做得很好！继续把<font color=#f80421>帅</font>移动到新的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10110303] = {id=10110303,chinese="做得非常好！再试试把<font color=#f80421>帅</font>移动到新的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10110304] = {id=10110304,chinese="做得真是太棒了！再试试把<font color=#f80421>帅</font>移动到新的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10110305] = {id=10110305,chinese="您真是非常非常优秀！接下来，我们提升下难度吧！",chinese_gs="",},
[10110401] = {id=10110401,chinese="这次需要移动<font color=#f80421>帅</font>两步，才能移动到<font color=#048404>星星</font>位置哟！试试吧！",chinese_gs="",},
[10110402] = {id=10110402,chinese="很好！这次需要移动<font color=#f80421>帅</font>三步，才能移动到<font color=#048404>星星</font>位置哟！试试吧！",chinese_gs="",},
[10110403] = {id=10110403,chinese="真是太棒了！这需要移动<font color=#f80421>帅</font>四步，才能移动到<font color=#048404>星星</font>位置哟！再试试吧！",chinese_gs="",},
[10110404] = {id=10110404,chinese="您简直太优秀了！接下来，我们试下吃子吧！",chinese_gs="",},
[10110501] = {id=10110501,chinese="拿起<font color=#f80421>帅</font>，吃掉旁边的<font color=#048404>黑马</font>吧！",chinese_gs="",},
[10110502] = {id=10110502,chinese="good！这继续用<font color=#f80421>帅</font>吃掉前面的<font color=#048404>黑车</font>！",chinese_gs="",},
[10110503] = {id=10110503,chinese="这次难度增加了哟！移动<font color=#f80421>帅</font>2步，吃掉<font color=#048404>黑卒</font>吧！",chinese_gs="",},
[10110504] = {id=10110504,chinese="加油！继续移动<font color=#f80421>帅</font>3步，吃掉<font color=#048404>黑马</font>吧！",chinese_gs="",},
[10110505] = {id=10110505,chinese="加油！继续移动<font color=#f80421>帅</font>3步，吃掉<font color=#048404>黑炮</font>吧！",chinese_gs="",},
[10110506] = {id=10110506,chinese="您简直太优秀！接下来，我们再提升下难度吧！",chinese_gs="",},
[10110601] = {id=10110601,chinese="这次提升下难度！需要您自行判断，用<font color=#f80421>帅</font>吃掉<font color=#048404>可以吃</font>的棋子！试试吧！",chinese_gs="",},
[10110602] = {id=10110602,chinese="做得很好，继续提升难度！请自行判断，用<font color=#f80421>帅</font>吃掉<font color=#048404>可以吃</font>的棋子！试试吧！",chinese_gs="",},
[10110603] = {id=10110603,chinese="再来提升下难度！需要你自行判断，用<font color=#f80421>帅</font>吃掉离他<font color=#048404>最少步数</font>的棋子！试试吧！",chinese_gs="",},
[10110604] = {id=10110604,chinese="继续提升下难度！需要你自行判断，用<font color=#f80421>帅</font>吃掉离他<font color=#048404>最多步数</font>的棋子！试试吧！",chinese_gs="",},
[10110605] = {id=10110605,chinese="您简直太优秀了！您已学会了如何走<font color=#f80421>帅</font>/<font color=#000000>将</font>，接下来，我们继续学习如何走<font color=#f80421>仕</font>/<font color=#000000>士</font>吧！",chinese_gs="",},
[10110606] = {id=10110606,chinese="帅不能走出九宫格哦！",chinese_gs="",},
[10110607] = {id=10110607,chinese="这不是最少步数的棋子哦！",chinese_gs="",},
[10110608] = {id=10110608,chinese="这不是最多步数的棋子哦！",chinese_gs="",},
[10111101] = {id=10111101,chinese="<font color=#f80421>仕</font>/<font color=#000000>士</font>是帅和将的贴身护卫,所以也只能在<font color=#048404>九宫格</font>内移动。",chinese_gs="",},
[10111102] = {id=10111102,chinese="<font color=#f80421>仕</font>/<font color=#000000>士</font>沿九宫格<font color=#048404>斜线</font>移动，且每次也只能移动<font color=#048404>一格</font>，棋盘所示位置点就是他们能走到的位置",chinese_gs="",},
[10111103] = {id=10111103,chinese="这里的两个<font color=#f80421>仕</font>均可向<font color=#048404>中心</font>斜线移动一格",chinese_gs="",},
[10111104] = {id=10111104,chinese="而这里的<font color=#000000>士</font>则可向<font color=#048404>左上、左下、右上、右下</font>四个方向移动一格",chinese_gs="",},
[10111105] = {id=10111105,chinese="同样的，学完走法，让我们继续学习<font color=#f80421>仕</font>/<font color=#000000>士</font>的吃子方法",chinese_gs="",},
[10111201] = {id=10111201,chinese="<font color=#f80421>仕</font>/<font color=#000000>士</font>的走棋和吃棋方式相同，只可<font color=#048404>沿斜线移动一格</font>吃子",chinese_gs="",},
[10111202] = {id=10111202,chinese="注意看这个星星，虽然星星在<font color=#f80421>仕</font>斜线上，但是因为在九宫外，所以<font color=#f80421>仕</font>不能吃它",chinese_gs="",},
[10111203] = {id=10111203,chinese="这个星星虽然在九宫内，但是它在<font color=#f80421>仕</font>的竖线前一格，所以<font color=#f80421>仕</font>也不能吃它",chinese_gs="",},
[10111204] = {id=10111204,chinese="只有这颗星星，在九宫内，且在在<font color=#f80421>仕</font>的斜线前一格，所以<font color=#f80421>仕</font>能立即吃它",chinese_gs="",},
[10111205] = {id=10111205,chinese="再看这颗星星，他在九宫仕斜线上，但是它在斜线前两格，所以也不能立即吃，需要移动两次才能吃掉",chinese_gs="",},
[10111206] = {id=10111206,chinese="同样这颗星星，虽然在九宫横线上，但是如果沿箭头走两次斜线，也是两步后吃掉它",chinese_gs="",},
[10111207] = {id=10111207,chinese="已经学得差不多了，接下来，就让我们去习题实操练习下怎么走<font color=#f80421>仕</font>和吃棋吧！",chinese_gs="",},
[10111301] = {id=10111301,chinese="选中<font color=#f80421>仕</font>，把他移动到<font color=#048404>星星</font>位置。",chinese_gs="",},
[10111302] = {id=10111302,chinese="做得很好！继续移动<font color=#f80421>仕</font>到新的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10111303] = {id=10111303,chinese="你真是太棒了！这次难一点，再试试把<font color=#f80421>仕</font>移动到远一点的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10111304] = {id=10111304,chinese="做得真是太棒了！再移动到新的<font color=#048404>星星</font>位置吧！这次需要思考下哟！",chinese_gs="",},
[10111305] = {id=10111305,chinese="你真是太棒了！这次难一点，再试试把<font color=#f80421>仕</font>移动到远一点的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10111306] = {id=10111306,chinese="做得真是太棒了！再移动到新的<font color=#048404>星星</font>位置吧！这次需要思考下哟！",chinese_gs="",},
[10111307] = {id=10111307,chinese="您真是非常非常优秀！接下来，我们提升下难度吧！",chinese_gs="",},
[10111401] = {id=10111401,chinese="选中<font color=#f80421>仕</font>，把他移动到<font color=#048404>星星</font>位置，这次需要移动2步才能到达哦。",chinese_gs="",},
[10111402] = {id=10111402,chinese="做得很好！继续移动<font color=#f80421>仕</font>到新的<font color=#048404>星星</font>位置吧！",chinese_gs="",},
[10111403] = {id=10111403,chinese="你真是太棒了！请继续移动！",chinese_gs="",},
[10111404] = {id=10111404,chinese="你真是太棒了！请继续移动！",chinese_gs="",},
[10111405] = {id=10111405,chinese="您真是非常非常优秀！接下来，我们试下吃子吧！",chinese_gs="",},
[10111501] = {id=10111501,chinese="拿起<font color=#f80421>仕</font>，吃掉右前方的<font color=#048404>黑卒</font>吧！",chinese_gs="",},
[10111502] = {id=10111502,chinese="继续用<font color=#f80421>仕</font>吃掉右前方的<font color=#048404>黑卒</font>！",chinese_gs="",},
[10111503] = {id=10111503,chinese="这次提升下难度！继续用<font color=#f80421>仕</font>吃掉<font color=#048404>黑马</font>！",chinese_gs="",},
[10111504] = {id=10111504,chinese="您简直太优秀！接下来，我们再提升下难度吧！",chinese_gs="",},
[10111601] = {id=10111601,chinese="难度提升了！请自行判断，用<font color=#f80421>仕</font>吃掉<font color=#048404>能吃</font>的棋子吧！",chinese_gs="",},
[10111602] = {id=10111602,chinese="不错哟！继续用<font color=#f80421>仕</font>吃掉<font color=#048404>可以吃</font>的棋子！",chinese_gs="",},
[10111603] = {id=10111603,chinese="难度提升！！继续用<font color=#f80421>仕</font>吃掉所有<font color=#048404>可以吃</font>的棋子！",chinese_gs="",},
[10111604] = {id=10111604,chinese="难度提升！！继续用<font color=#f80421>仕</font>吃掉所有<font color=#048404>可以吃</font>的棋子！",chinese_gs="",},
[10111605] = {id=10111605,chinese="您简直太优秀了！您已学会了如何走<font color=#f80421>帅</font>/<font color=#000000>将</font>，接下来，我们继续学习如何走<font color=#f80421>仕</font>/<font color=#000000>士</font>吧！",chinese_gs="",},
[10111606] = {id=10111606,chinese="<font color=#f80421>仕</font>只能沿九宫<font color=#048404>斜线</font>上吃棋子哟！",chinese_gs="",},
[10111701] = {id=10111701,chinese="把<font color=#f80421>红马</font>用最少步数移动到星星位置！",chinese_gs="",},
[10111702] = {id=10111702,chinese="黑方的<font color=#000000>马</font>上了一步，看起来你似乎能吃它？",chinese_gs="",},
[10111703] = {id=10111703,chinese="但是注意，这里还有个<font color=#000000>马</font>在保护它！",chinese_gs="",},
[10111704] = {id=10111704,chinese="所以，千万不要吃黑马，继续前进到星星位置，将军！",chinese_gs="",},
[10111705] = {id=10111705,chinese="接下来，我们按棋谱走出《橘中秘》的顺炮横车局",chinese_gs="",},
[10111706] = {id=10111706,chinese="请走出<font color=#048404>{0}</font>！",chinese_gs="",},
[10111707] = {id=10111707,chinese="请用<font color=#f80421>双车错</font>赢得胜利！",chinese_gs="",},
[10111708] = {id=10111708,chinese="您移动的步数不是最少步数哟！",chinese_gs="",},
[10111709] = {id=10111709,chinese="你仅需一步就能到达星星位置！",chinese_gs="",},
[10111710] = {id=10111710,chinese="请按棋谱移动棋子！",chinese_gs="",},
[10111711] = {id=10111711,chinese="请使用双车错将死对方！",chinese_gs="",},
